#include <zephyr/ztest.h>
#include <zephyr/storage/stream_flash.h>
#include <zephyr/drivers/flash.h>
#include <string.h>

#define SF_PAGE_SIZE 256
#define SF_PAGE_COUNT 4
#define SF_FS_SIZE (SF_PAGE_COUNT * SF_PAGE_SIZE)
#define SF_BUF_SIZE 32

static uint8_t flash_area[SF_FS_SIZE];
static uint32_t pages_written;
static uint32_t bytes_written;

static const struct device *const fdev = DEVICE_DT_GET(DT_NODELABEL(flash_controller));

static void flash_mock_init(void)
{
	const struct flash_parameters *params = flash_get_parameters(fdev);

	memset(flash_area, params->erase_value, sizeof(flash_area));
	pages_written = 0;
	bytes_written = 0;
}

static uint32_t flash_mock_pages_written(void)
{
	return pages_written;
}

static uint32_t flash_mock_bytes_written(void)
{
	return bytes_written;
}

static void *stream_flash_setup(void)
{
	flash_mock_init();

	return NULL;
}

ZTEST(lib_stream_flash, test_stream_flash_init_ok)
{
	uint8_t buf[SF_BUF_SIZE];
	int rc;
	struct stream_flash_ctx s;

	rc = stream_flash_init(&s, fdev, buf, sizeof(buf), 0, SF_FS_SIZE, NULL);
	zassert_ok(rc, "init failed");
}

ZTEST(lib_stream_flash, test_stream_flash_init_no_flash_dev)
{
	uint8_t buf[SF_BUF_SIZE];
	int rc;
	struct stream_flash_ctx s;

	rc = stream_flash_init(&s, NULL, buf, sizeof(buf), 0, SF_FS_SIZE, NULL);
	zassert_equal(rc, -EINVAL, "should fail with EINVAL");
}

ZTEST(lib_stream_flash, test_stream_flash_init_no_buf)
{
	int rc;
	struct stream_flash_ctx s;

	rc = stream_flash_init(&s, fdev, NULL, SF_BUF_SIZE, 0, SF_FS_SIZE, NULL);
	zassert_equal(rc, -EINVAL, "should fail with EINVAL");
}

ZTEST(lib_stream_flash, test_stream_flash_init_buf_too_small)
{
	uint8_t buf[SF_BUF_SIZE];
	int rc;
	struct stream_flash_ctx s;

	rc = stream_flash_init(&s, fdev, buf, 0, 0, SF_FS_SIZE, NULL);
	zassert_equal(rc, -EINVAL, "should fail with EINVAL");
}

ZTEST(lib_stream_flash, test_stream_flash_buf_size_greater_than_page_size)
{
	const struct flash_parameters *params = flash_get_parameters(fdev);
	uint8_t buf[params->page_size + 1];
	int rc;
	struct stream_flash_ctx s;

	rc = stream_flash_init(&s, fdev, buf, sizeof(buf), 0, 0, NULL);
	zassert_equal(rc, -EINVAL, "should fail with EINVAL");

	rc = stream_flash_init(&s, fdev, buf, sizeof(buf), 0, SF_FS_SIZE, NULL);
	zassert_equal(rc, -EINVAL, "should fail with EINVAL");
}

ZTEST(lib_stream_flash, test_stream_flash_buffered_write)
{
	uint8_t buf[SF_BUF_SIZE];
	uint8_t data[SF_BUF_SIZE];
	int rc;
	struct stream_flash_ctx s;

	flash_mock_init();
	rc = stream_flash_init(&s, fdev, buf, sizeof(buf), 0, SF_FS_SIZE, NULL);
	zassert_ok(rc, "init failed");

	rc = stream_flash_write(&s, data, sizeof(data));
	zassert_ok(rc, "write failed");

	rc = stream_flash_flush(&s);
	zassert_ok(rc, "flush failed");

	zassert_equal(flash_mock_pages_written(), 1, "incorrect page writes");
	zassert_equal(flash_mock_bytes_written(), sizeof(data), "incorrect bytes written");
}

ZTEST(lib_stream_flash, test_stream_flash_buffered_write_available_offbyone)
{
	uint8_t buf[SF_BUF_SIZE];
	uint8_t data[SF_BUF_SIZE + 1];
	int rc;
	struct stream_flash_ctx s;

	flash_mock_init();
	rc = stream_flash_init(&s, fdev, buf, sizeof(buf), 0, SF_FS_SIZE, NULL);
	zassert_ok(rc, "init failed");

	/* write buffer full except one byte */
	rc = stream_flash_write(&s, data, sizeof(buf) - 1);
	zassert_ok(rc, "write failed");

	/* one byte left, write two bytes */
	rc = stream_flash_write(&s, data, 2);
	zassert_not_equal(rc, -ENOMEM, "write should not fail with ENOMEM");
	zassert_ok(rc, "write failed");

	rc = stream_flash_flush(&s);
	zassert_ok(rc, "flush failed");

	zassert_equal(flash_mock_pages_written(), 2, "incorrect page writes");
	zassert_equal(flash_mock_bytes_written(), sizeof(buf) - 1 + 2,
		      "incorrect bytes written");
}

ZTEST_SUITE(lib_stream_flash, NULL, stream_flash_setup, NULL, NULL, NULL);
